      criteria: criteria.map(item => ({

        criterion_id: item.json.criterion_id,

        criterion_no: item.json.criterion_no,

        criterion_title: item.json.criterion_title,

        co: item.json.co,

        description: item.json.description,

        max_score: item.json.max_score

      }))

    }

  }

