const scoreForm = $input.first().json;

// Original information from Form 1

const originalForm = $('Student & Review Details').first().json;

// Criteria retrieved from Supabase

const criteria = $('Get Evaluation Criteria').all();

const scores = criteria.map((item) => {

  const criterion = item.json;

  const selectedValue = scoreForm[criterion.criterion_title];

  const score = selectedValue

    ? parseInt(String(selectedValue).split(' - ')[0], 10)

    : null;

  return {

    criterion_id: criterion.criterion_id,

    criterion_no: criterion.criterion_no,

    criterion_title: criterion.criterion_title,

    co: criterion.co,

    score: score

  };

});

// Calculate Review total

const totalMarks = scores.reduce(

  (total, item) => total + (item.score || 0),

  0

);

return [

  {

    json: {

      student_name: originalForm["Student Name"],

      roll_number: originalForm["Roll Number"],

      team_number: originalForm["Team Number"],

      project_title: originalForm["Project Title"],

      review_type: originalForm["Review Type"],

      review_date: originalForm["Review Date"],

      total_marks: totalMarks,

      max_marks: 40,

      percentage: Number(((totalMarks / 40) * 100).toFixed(2)),

      scores: scores

    }

  }

];

const items = $input.all();

const student = items.find(

  item => item.json.student_id !== null && item.json.student_id !== undefined

);

if (!student) {

  throw new Error('No valid student_id found in Merge output');

}

return [

  {

    json: student.json

  }

];

const items = $input.all();

const team = items.find(

  item => item.json.team_id !== null && item.json.team_id !== undefined

);

if (!team) {

  throw new Error('No valid team_id found in Merge Team output');

}

return [

  {

    json: team.json

  }

];

// Get ALL records directly from Find Review 2 Scores
const scores = $('Find Review 2 Scores').all();

// Safety check
if (scores.length === 0) {
  return [
    {
      json: {
        review_id: 2,
        student_id: null,
        number_of_scores: 0,
        total_marks: 0,
        max_marks: 40,
        percentage: 0
      }
    }
  ];
}

// Get student ID
const studentId = scores[0].json.student_id;

// Calculate total of all Review 2 scores
const totalMarks = scores.reduce(
  (total, item) => {
    return total + Number(item.json.score || 0);
  },
  0
);

// Maximum marks for Review 2
const maxMarks = 40;

// Calculate percentage
const percentage = (totalMarks / maxMarks) * 100;

// Return result
return [
  {
    json: {
      review_id: 2,
      student_id: studentId,
      number_of_scores: scores.length,
      total_marks: totalMarks,
      max_marks: maxMarks,
      percentage: Number(percentage.toFixed(2))
    }
  }
];

const scores = $('Find Review 1 Scores').all();

if (scores.length === 0) {

  return [

    {

      json: {

        review_id: 1,

        student_id: null,

        total_marks: 0,

        max_marks: 40,

        percentage: 0

      }

    }

  ];

}

const studentId = scores[0].json.student_id;

const totalMarks = scores.reduce((total, item) => {

  return total + Number(item.json.score || 0);

}, 0);

const maxMarks = 40;

const percentage = (totalMarks / maxMarks) * 100;

return [

  {

    json: {

      review_id: 1,

      student_id: studentId,

      total_marks: totalMarks,

      max_marks: maxMarks,

      percentage: Number(percentage.toFixed(2))

    }

  }

];

const evaluation = $('Prepare Evaluation Result').first().json;

// Review comes from either:

// TRUE  → Use Existing Review

// FALSE → Create Project Review

const review = ($('Merge Review Data').all().map(i => i.json).find(r => r?.review_id != null)) || {};

// Student comes from:

// Merge Student & Team

const student = $('Merge Student & Team').first().json;

// Validate Review ID

if (!review?.review_id) {

  throw new Error('Review ID not found from Merge Review Data');

}

// Validate Student ID

if (!student?.student_id) {

  throw new Error('Student ID not found from Create Team Member');

}

// Validate evaluation scores

if (!evaluation?.scores || !Array.isArray(evaluation.scores)) {

  throw new Error('Evaluation scores not found from Prepare Evaluation Result');

}

// Prepare one record for each criterion score

return evaluation.scores.map(item => ({

  json: {

    review_id: review.review_id,

    student_id: student.student_id,

    criterion_id: item.criterion_id,

    score: item.score

  }

}));

const items = $input.all();

const first = items[0].json;

const reviewId = first.review_id;

const studentId = first.student_id;

const totalMarks = items.reduce((sum, item) => {

  return sum + Number(item.json.score || 0);

}, 0);

const maxMarks = items.length * 4;

const percentage = (totalMarks / maxMarks) * 100;

return [

  {

    json: {

      review_id: reviewId,

      student_id: studentId,

      total_marks: totalMarks,

      max_marks: maxMarks,

      percentage: Number(percentage.toFixed(2))

    }

  }

];

// Get Review 1 result directly

const review1 = $('Calculate Review 1 Result').first()?.json;

// Get Review 2 result directly

const review2 = $('Calculate Review 2 Result').first()?.json;


// Get student ID

const studentId =

  review1?.student_id ??

  review2?.student_id ??

  $('Merge Student & Team').first()?.json?.student_id ??

  null;


// Get Review 1 marks

const review1Marks = Number(

  review1?.total_marks ?? 0

);


// Get Review 2 marks

const review2Marks = Number(

  review2?.total_marks ?? 0

);


// Maximum marks

const review1MaxMarks = 40;

const review2MaxMarks = 40;


// Calculate cumulative marks

const cumulativeMarks =

  review1Marks + review2Marks;


// Maximum cumulative marks

const cumulativeMaxMarks =

  review1MaxMarks + review2MaxMarks;


// Calculate percentage

const percentage =

  (cumulativeMarks / cumulativeMaxMarks) * 100;


// Return final result

return [

  {

    json: {

      student_id: studentId,

      review_1_marks: review1Marks,

      review_1_max_marks: review1MaxMarks,

      review_2_marks: review2Marks,

      review_2_max_marks: review2MaxMarks,

      cumulative_marks: cumulativeMarks,

      cumulative_max_marks: cumulativeMaxMarks,

      percentage: Number(

        percentage.toFixed(2)

      )

    }

  }

];

// ==========================================
// GET DATA FROM PREVIOUS NODES
// ==========================================

const criteria = $('Get Evaluation Criteria1').all();

const review1Scores = $('Find Review 1 Scores').all();

const review2Scores = $('Find Review 2 Scores').all();

const cumulative = $('Calculate Cumulative Result').first().json;


// ==========================================
// REVIEW 1 CRITERIA
// ==========================================

const review1Criteria = criteria
  .filter(item =>
    String(item.json.review_type).trim().toUpperCase() === 'REVIEW_1'
  )
  .map(item => {

    const criterion = item.json;

    const scoreRecord = review1Scores.find(
      score =>
        Number(score.json.criterion_id) ===
        Number(criterion.criterion_no)
    );

    return {
      criterion_no: Number(criterion.criterion_no),
      criterion_id: Number(criterion.criterion_id),
      criterion_title: criterion.criterion_title,
      co: criterion.co,
      description: criterion.description,

      score: scoreRecord
        ? Number(scoreRecord.json.score)
        : 0,

      max_score: Number(criterion.max_score || 4),

      remarks: scoreRecord?.json?.remarks || null
    };
  });


// ==========================================
// REVIEW 2 CRITERIA
// ==========================================

const review2Criteria = criteria
  .filter(item =>
    String(item.json.review_type).trim().toUpperCase() === 'REVIEW_2'
  )
  .map(item => {

    const criterion = item.json;

    const scoreRecord = review2Scores.find(
      score =>
        Number(score.json.criterion_id) ===
        Number(criterion.criterion_no)
    );

    return {
      criterion_no: Number(criterion.criterion_no),
      criterion_id: Number(criterion.criterion_id),
      criterion_title: criterion.criterion_title,
      co: criterion.co,
      description: criterion.description,

      score: scoreRecord
        ? Number(scoreRecord.json.score)
        : 0,

      max_score: Number(criterion.max_score || 4),

      remarks: scoreRecord?.json?.remarks || null
    };
  });


// ==========================================
// FINAL AI REPORT DATA
// ==========================================

return [
  {
    json: {

      student_id: cumulative.student_id,

      // --------------------------------------
      // REVIEW 1
      // --------------------------------------

      review_1: {
        total_marks: cumulative.review_1_marks,
        max_marks: cumulative.review_1_max_marks,

        percentage:
          Number(
            (
              cumulative.review_1_marks /
              cumulative.review_1_max_marks
            ) * 100
          ).toFixed(2),

        criteria: review1Criteria
      },


      // --------------------------------------
      // REVIEW 2
      // --------------------------------------

      review_2: {
        total_marks: cumulative.review_2_marks,
        max_marks: cumulative.review_2_max_marks,

        percentage:
          Number(
            (
              cumulative.review_2_marks /
              cumulative.review_2_max_marks
            ) * 100
          ).toFixed(2),

        criteria: review2Criteria
      },


      // --------------------------------------
      // CUMULATIVE RESULT
      // --------------------------------------

      cumulative_result: {
        total_marks: cumulative.cumulative_marks,
        max_marks: cumulative.cumulative_max_marks,
        percentage: cumulative.percentage
      }

    }
  }
];

// Get Student Details
const student = $('Get Student Details').first().json;

// Get Team Membership
const membership = $('Get Team Membership').first().json;

// Get Project Details
const project = $('Get Project Details').first().json;

// Get complete Review + Cumulative data
const report = $('Get Evaluation Criteria3').first().json;


// Build final report data
return [
  {
    json: {
      // -------------------------
      // STUDENT DETAILS
      // -------------------------
      student: {
        student_id: student.student_id,
        student_name: student.student_name,
        roll_no: student.roll_no,
        email: student.email,
        phone: student.phone
      },

      // -------------------------
      // TEAM / PROJECT DETAILS
      // -------------------------
      project: {
        team_id: project.team_id,
        team_number: project.team_number,
        project_title: project.project_title,
        supervisor_id: project.supervisor_id
      },

      // -------------------------
      // REVIEW 1
      // -------------------------
      review_1: report.review_1,

      // -------------------------
      // REVIEW 2
      // -------------------------
      review_2: report.review_2,

      // -------------------------
      // CUMULATIVE RESULT
      // -------------------------
      cumulative_result: report.cumulative_result
    }
  }
];

const ai = $input.first().json;

const report = ai.output || "";

const source = $('Prepare Final Report').first().json;

return [

  {

    json: {

      student_id: source.student.student_id,

      student_name: source.student.student_name,

      roll_no: source.student.roll_no,

      email: source.student.email,

      team_id: source.project.team_id,

      team_number: source.project.team_number,

      project_title: source.project.project_title,

      review_1_marks: source.review_1.total_marks,

      review_1_max_marks: source.review_1.max_marks,

      review_1_percentage: source.review_1.percentage,

      review_2_marks: source.review_2.total_marks,

      review_2_max_marks: source.review_2.max_marks,

      review_2_percentage: source.review_2.percentage,

      cumulative_marks: source.cumulative_result.total_marks,

      cumulative_max_marks: source.cumulative_result.max_marks,

      cumulative_percentage: source.cumulative_result.percentage,

      ai_report: report

    }

  }

];
